const SKILL_ID = "phasegent";
const SKILL_PATH = "/builtin/phasegent.md";

const ROLE_SKILLS = [
  {
    id: "phasegent-orchestrator",
    path: "/builtin/phasegent-orchestrator.md",
    content: SKILL_ORCHESTRATOR_CONTENT,
  },
  {
    id: "phasegent-executor",
    path: "/builtin/phasegent-executor.md",
    content: SKILL_EXECUTOR_CONTENT,
  },
  {
    id: "phasegent-reviewer",
    path: "/builtin/phasegent-reviewer.md",
    content: SKILL_REVIEWER_CONTENT,
  },
];

// The host lists this description in the skill index, so it is derived from the
// embedded frontmatter: the listed skill and its body can never disagree.
function frontmatterDescription(content) {
  const match = String(content).match(/^description:[ \t]*(.+)$/m);
  return match ? match[1].trim() : "";
}

function skillDefinition() {
  return {
    id: SKILL_ID,
    name: SKILL_ID,
    path: SKILL_PATH,
    description: frontmatterDescription(SKILL_CONTENT),
    content: SKILL_CONTENT,
  };
}

function roleSkillDefinitions() {
  return ROLE_SKILLS.map(({ id, path, content }) => ({
    id,
    name: id,
    path,
    description: frontmatterDescription(content),
    content,
  }));
}

function skillDefinitions() {
  return [skillDefinition(), ...roleSkillDefinitions()];
}

async function registerSkill(context) {
  const skill = context && context.skill;
  const transform = skill && skill.transform;
  if (typeof transform !== "function") {
    warn("phasegent: host exposes no skill.transform; the phasegent skill stays unregistered");
    return null;
  }
  const definitions = skillDefinitions();
  return await transform((draft) => {
    // A throw inside a transform callback disables the whole plugin (redirect
    // hook included), so an unknown draft shape only warns.
    if (!draft || typeof draft.add !== "function") {
      warn("phasegent: host skill draft exposes no add; the phasegent skill stays unregistered");
      return;
    }
    try {
      for (const definition of definitions) draft.add(definition);
    } catch (error) {
      warn(`phasegent: skill registration was rejected (${errorText(error)})`);
    }
  });
}

// assets/opencode/src/agents.js
// v2 agent.transform: bind each protocol agent to its own slim role skill.
//
// The role skill is prepended to the agent's `system`, so it is the stable
// prefix of that agent's system prompt and a delegation only has to carry the
// issue number. The agent is matched by id (task-spawned children use the same
// ids), and only the three protocol agents are bound: `explore` stays a
// recon-only role and keeps the reviewer capability rewrite without inheriting
// the reviewer protocol surface.
//
// The live v2.0.12 draft is `{ list, get, default, update, remove }` with
// `update(id, mutate)` mutating the live agent info. The host resolves plugin
// `setup` before it materializes the configured agents and never re-runs an
// already-registered callback, so the binding runs one attempt inline and the
// rest detached on a bounded backoff, replacing the previous callback instead
// of stacking it. A host whose draft has no `update` keeps the skills
// registered as inert metadata and warns.


const ROLE_SKILL_BINDINGS = [
  ["orchestrator", "phasegent-orchestrator"],
  ["executor", "phasegent-executor"],
  ["reviewer", "phasegent-reviewer"],
];

// Total worst case ~0.8s, and only when the host never materializes a protocol
// agent (a host without the phasegent agents at all).
const AGENT_BIND_BACKOFF_MS = [0, 10, 25, 50, 100, 200, 400];

function roleSkillId(agentId) {
  const agent = typeof agentId === "string" ? agentId.toLowerCase() : "";
  if (!agent) return null;
  for (const [hint, skillId] of ROLE_SKILL_BINDINGS) {
    if (agent.includes(hint)) return skillId;
  }
  return null;
}

function roleSkillContent(skillId) {
  const entry = ROLE_SKILLS.find((candidate) => candidate.id === skillId);
  return entry ? entry.content : null;
}

// Idempotent prefixing: the host re-runs the callback on every agent-state
// invalidation, and a repeated pass must not stack the skill body.
function withSkillPrefix(system, content) {
  const current = typeof system === "string" ? system : "";
  if (current.startsWith(content)) return current;
  return current.length > 0 ? `${content}\n${current}` : content;
}

// One registration pass: prepend each present protocol agent's own skill and
// report how many protocol agents were seen and how many are bound now.
function bindPresentAgents(draft) {
  const protocol = [];
  for (const info of draft.list()) {
    const id = info && typeof info.id === "string" ? info.id : "";
    if (roleSkillId(id)) protocol.push(id);
  }
  let bound = 0;
  for (const id of protocol) {
    const content = roleSkillContent(roleSkillId(id));
    if (!content) continue;
    draft.update(id, (entry) => {
      if (!entry || typeof entry !== "object") return;
      entry.system = withSkillPrefix(entry.system, content);
    });
    bound += 1;
  }
  return { protocol, bound };
}

async function registerAgentSkills(context, deps) {
  const agent = context && context.agent;
  const transform = agent && agent.transform;
  if (typeof transform !== "function") {
    warn("phasegent: host exposes no agent.transform; role skills stay inert metadata and are not injected");
    return null;
  }
  const backoff = (deps && deps.backoff) || AGENT_BIND_BACKOFF_MS;
  const wait = (deps && deps.wait) || ((ms) => new Promise((resolve) => setTimeout(resolve, ms)));
  const holder = { registration: null, disposed: false, settled: false, bound: 0, seen: new Set() };

  const runAttempt = async () => {
    if (holder.disposed) return;
    const previous = holder.registration;
    holder.registration = await transform((draft) => {
      if (!draft || typeof draft.list !== "function" || typeof draft.update !== "function") {
        warn("phasegent: host agent draft exposes no update; role skills stay inert metadata and are not injected");
        return;
      }
      try {
        const pass = bindPresentAgents(draft);
        for (const id of pass.protocol) holder.seen.add(id);
        holder.bound = pass.bound;
      } catch (error) {
        warn(`phasegent: role skill injection was rejected (${errorText(error)})`);
      }
    });
    // Replace the stale callback: it would otherwise keep re-running on every
    // agent-state invalidation for the lifetime of the plugin.
    if (previous && typeof previous.dispose === "function") {
      try {
        await previous.dispose();
      } catch (_) {
        // A failed dispose only leaves an extra inert callback registered.
      }
    }
    if (holder.bound > 0 && holder.bound >= holder.seen.size) holder.settled = true;
  };

  await runAttempt();
  // The host resolves `setup` first and materializes the configured agents
  // afterwards; a callback registered while setup is still awaiting therefore
  // only ever sees the built-in agents, and the host never re-runs it for a
  // later load. The remaining attempts run detached on a bounded backoff so
  // setup stays non-blocking, and they stop as soon as every protocol agent
  // that appeared is bound.
  const settle = (async () => {
    for (let index = 1; index < backoff.length && !holder.settled; index += 1) {
      await wait(backoff[index]);
      if (holder.disposed) return;
      await runAttempt();
    }
    if (!holder.settled && holder.bound === 0) {
      warn("phasegent: no protocol agent was found; role skills stay inert metadata and are not injected");
    }
  })().catch((error) => {
    warn(`phasegent: role skill binding failed (${errorText(error)})`);
  });

  return {
    settle,
    async dispose() {
      holder.disposed = true;
      const registration = holder.registration;
      if (registration && typeof registration.dispose === "function") {
        await registration.dispose();
      }
    },
  };
}

// assets/opencode/src/strategy.js
// v2 worktree strategy. `editor.add` selects the strategy as the default, and
// the v2 editor has no way to wrap the host git strategy, so the strategy is
// only claimed when the checkout is already phasegent-bound; otherwise the host
// keeps its own git implementation. A host "create worktree" action is the
// explicit isolation opt-in (issue 616), so `create` passes `isolate` and a
// dedicated directory is really created instead of quietly reusing the current
// checkout.


// Mirrors the host git strategy's command (packages/core/src/git.ts:657) so a
// failed lease never breaks worktree creation in a phasegent checkout.
async function gitWorktreeAdd(input) {
  const directory = input && input.directory;
  const sourceDirectory = input && input.sourceDirectory;
  if (typeof directory !== "string" || directory.length === 0) {
    throw new Error("phasegent: worktree create requires a destination directory");
  }
  const ref = input && typeof input.branch === "string" && input.branch.length > 0
    ? input.branch
    : "HEAD";
  const command = Bun.$`git worktree add --detach -- ${directory} ${ref}`;
  const result = await safeText((sourceDirectory ? command.cwd(sourceDirectory) : command).quiet());
  if (!result.ok) {
    throw new Error(`phasegent: git worktree add failed: ${result.error}`);
  }
  return { directory };
}

function worktreeStrategyDefinition(options) {
  const issueId = options.issueId;
  const fallbackDirectory = options.directory;
  return {
    id: "phasegent",
    async create(input) {
      const sourceDirectory = input && typeof input.sourceDirectory === "string"
        ? input.sourceDirectory
        : fallbackDirectory;
      // A host "create worktree" action is the explicit opt-in (issue 616):
      // without `--isolate` the acquire may reuse the current checkout, which
      // would not honour the create request.
      const acquired = await options.acquire(issueId, null, sourceDirectory, { isolate: true });
      if (acquired && typeof acquired.path === "string" && acquired.path.length > 0) {
        return { directory: acquired.path };
      }
      warn("phasegent: worktree acquire failed; falling back to a plain git worktree");
      return await options.gitAdd(input);
    },
    async remove() {
      // Retain the worktree and its branch; release/removal stays with
      // `phasegent worktree prune` so no lease is orphaned by a host action.
      return;
    },
    async list(sourceDirectory) {
      const root = typeof sourceDirectory === "string" && sourceDirectory.length > 0
        ? sourceDirectory
        : fallbackDirectory;
      const entries = [];
      const seen = new Set();
      const push = (directory, type) => {
        if (typeof directory !== "string" || directory.length === 0) return;
        if (seen.has(directory)) return;
        seen.add(directory);
        entries.push({ directory, type });
      };
      push(root, "root");
      const leases = await options.readLeases(issueId, root);
      for (const lease of leases || []) {
        if (!lease || typeof lease !== "object") continue;
        push(lease.worktree_path, "worktree");
      }
      return entries;
    },
  };
}

// `deps` is an internal seam so tests can exercise the strategy without the
// phasegent CLI; production callers pass nothing. `PHASEGENT_WORKTREE_NO_DISCOVER=1`
// keeps the adapter from running the CLI at all, and then the host keeps its own
// git strategy. The binding is probed once per plugin instance: a checkout that
// gains its binding later keeps the host git strategy until the plugin reloads.
async function registerWorktreeStrategy(context, deps) {
  if (phasegentCallsDisabled()) return null;
  const worktree = context && context.worktree;
  const transform = worktree && worktree.transform;
  if (typeof transform !== "function") {
    warn("phasegent: host exposes no worktree.transform; the git strategy stays in place");
    return null;
  }
  const directory = locationDirectory(context);
  const readBinding = (deps && deps.readBinding) || readBranchBinding;
  const issueId = await readBinding(directory);
  if (!issueId) return null;
  const definition = worktreeStrategyDefinition({
    issueId,
    directory,
    acquire: (deps && deps.acquire) || acquireWorktree,
    gitAdd: (deps && deps.gitAdd) || gitWorktreeAdd,
    readLeases: (deps && deps.readLeases) || readIssueLeases,
  });
  return await transform((editor) => {
    editor.add(definition);
  });
}

// assets/opencode/src/index.js
// OpenCode v2 worktree adapter — source entry.
//
// The deployable artifact is the checked-in single file
// `assets/opencode/phasegent-worktree.js`, generated from this tree by
// `bun run build:plugin` (see `build.js`); prompt bodies are inlined at build
// time from `skills/phasegent/*.md`, and the runtime never reads a file.
//
// OpenCode >= 2.0 is required: the v1 plugin shape is rejected by the v2 module
// loader (`PluginModule.LoadError: Plugin must export a default definition with
// an id and an effect or setup function.`,
// packages/core/src/plugin/module.ts:60-73, :111). The v2 contract is
// `export default { id, setup }`; `setup(context)` registers hooks imperatively
// and returns a cleanup (packages/plugin/src/promise/plugin.ts:56-61).
//
//   * `context.tool.hook("execute.before", event)` — one mutable event
//     `{ tool, sessionID, agent, messageID, id, input }`; core continues with the
//     returned `event.input` (packages/core/src/tool.ts:103-111, :271-280), so
//     relative path arguments and a bare/relative shell `workdir` are rewritten in
//     place.
//   * `context.worktree.transform(editor => editor.add({ id, create, remove, list }))`
//     (packages/plugin/src/promise/worktree.ts:5-22). It has no v1 `target`
//     callback, so the acquired worktree becomes the session directory through
//     `context.session.move` (packages/core/src/session/move.ts:41-49). The strategy
//     is only claimed when the checkout already carries a phasegent issue binding,
//     so a non-phasegent project keeps the host git strategy.
//   * `context.skill.transform(draft => draft.add({ id, name, description, path, content }))`
//     registers the embedded `phasegent` skill. The live v2.0.11
//     runtime draft is `{ list, get, add, update, remove }`, and `add` takes the
//     same flat `Skill.Info` the host's builtin skills use; the typed SDK's
//     `source({ type: "embedded", skill })` draft does not exist at runtime.
//   * `context.agent.transform(draft => draft.update(id, mutate))` binds each
//     protocol agent to its own slim skill: the skill body is prepended to the
//     agent's `system`, so the role skill is the stable, cacheable prefix of
//     that agent's system prompt. The live v2.0.12 draft is
//     `{ list, get, default, update, remove }`, and `update` mutates the live
//     agent info (its `system` included). The callback is re-run whenever the
//     agent state invalidates, so the prefix is applied idempotently.
//   * No slash command: the live v2.0.11 command draft exposes only
//     `add({ name, description, execute })`, and `execute` must return an
//     Effect that a promise plugin cannot build. Registering through the
//     typed SDK's `update(name, mutate)` draft raised a `TypeError` and the
//     host then disabled the whole plugin, redirect hook included (issue #533
//     host evidence), so `phasegent worktree acquire` stays the manual path.
//
// The npm `@opencode-ai/plugin` type package can lag the binary it ships with
// (`tool`, `worktree`, `session` and `location` are absent from 1.18.25 while
// the binary exposes them); the adapter targets the binary's runtime context.
//
// Session identity is `event.sessionID`, and a Task-spawned child reads its
// `parentID` through `context.session.get` so it inherits the parent's directory
// instead of guessing from the most recently remembered worktree (session.js).
// Degradation is deliberate: no binding or a failed acquire keeps the original
// directory and warns on the console (v2 has no structured warning channel). A
// lease row that `issue close` / `issue sync` converged keeps its "issue
// closed…" release reason, so the lazy path refuses to acquire a fresh worktree
// for an already closed issue and stays in place (issue #575 P2). Absolute paths
// pass through untouched, so an explicit escape and the external_directory check
// that guards it are never rewritten. All worktree calls stay local: no network,
// no credentials, no .env copies. Branches and directories are never deleted
// here; removal is `phasegent worktree prune`.


const PhasegentWorktreePlugin = {
  id: "phasegent-worktree",
  async setup(context) {
    const registrations = [];
    try {
      const strategy = await registerWorktreeStrategy(context);
      if (strategy) registrations.push(strategy);
    } catch (error) {
      warn(`phasegent: worktree strategy registration failed (${errorText(error)})`);
    }
    try {
      const hook = context && context.tool && context.tool.hook;
      if (typeof hook === "function") {
        registrations.push(await hook("execute.before", createRedirectHook(context)));
      } else {
        warn("phasegent: host exposes no tool hook; path redirection is disabled");
      }
    } catch (error) {
      warn(`phasegent: tool.execute.before registration failed (${errorText(error)})`);
    }
    try {
      const skill = await registerSkill(context);
      if (skill) registrations.push(skill);
    } catch (error) {
      warn(`phasegent: skill.transform registration failed (${errorText(error)})`);
    }
    try {
      const bound = await registerAgentSkills(context);
      if (bound) registrations.push(bound);
    } catch (error) {
      warn(`phasegent: agent.transform registration failed (${errorText(error)})`);
    }
    return async () => {
      for (const registration of registrations) {
        try {
          if (registration && typeof registration.dispose === "function") {
            await registration.dispose();
          }
        } catch (_) {
        }
      }
    };
  },
};

PhasegentWorktreePlugin.redirect = Object.freeze({
  isAbsolutePath,
  redirectPathValue,
  redirectPaths,
  agentRole,
  isSubagentSession,
  sessionPlaced,
  rewritePhasegentCommand,
  rememberWorktree,
  worktreeForSession,
  resetWorktrees,
  createRedirectHook,
  pickActiveWorktreePath,
  issueClosedLocally,
  discoverWorktreeForSession,
  ensureSessionWorktree,
  moveSessionToWorktree,
  readSessionInfo,
  inheritedWorktree,
  readBranchBinding,
  acquireWorktree,
  readIssueLeases,
  readIssueLeaseHistory,
  registerWorktreeStrategy,
  worktreeStrategyDefinition,
  gitWorktreeAdd,
  registerSkill,
  skillDefinition,
  roleSkillDefinitions,
  skillDefinitions,
  registerAgentSkills,
  roleSkillId,
  roleSkillContent,
  withSkillPrefix,
});

export default PhasegentWorktreePlugin;
